#include <iostream>
#include <string>
#include <cctype>

int main() {
    std::string line;
    std::getline(std::cin, line);
    bool start = true;
    for (char& c : line) {
        unsigned char u = static_cast<unsigned char>(c);
        if (c == ' ') {
            start = true;
            continue;
        }
        c = static_cast<char>(start ? std::toupper(u) : std::tolower(u));
        start = false;
    }
    std::cout << line << '\n';
}

